      this.participantsLoading = true
      try {
        await removeUserToScheduling_service({venue: this.venue.id, scheduling: this.scheduling.id, users: [userItem], source: 'WEB'})
        await this.fetchBooking({initial: false, participantsOnly: true})
        this.$emit('updated')
      } finally {
        this.participantsLoading = false
      }
