import {
    createNewPrice_SERVICE,
  deleteNewPrice_SERVICE,
  editNewPrice_SERVICE,
  filterScheduling_service,
  getAllBookingReactive, getConflictScheduling_service, getDashboard_service, getFareLessons_service, getFareSplit_service,
  getPrice_SERVICE,
  getSchedulingById_service, searchBooking_service, searchCourtsAvailable
} from "stores/core/services/booking-service";
import {get} from "lodash";
import {useBookingStore} from "stores/booking-store";
import {useVenueStore} from "stores/venue-store";
import {changeLoading} from "stores/core/controller/securityController";
import {getUser_service} from "stores/core/services/loyalty-service";
import {getAllSlots_service} from "stores/core/services/payments-service";
import moment from "moment";

export const allSchedulingReactive = (dates: string[]) => {
  const scheduling = getAllBookingReactive(dates)

  const snapshot = scheduling.onSnapshot(async (payload: any) => {
    const allEvents = Promise.all(payload.docs.map(async (p: any) => {
      const users = await p.ref.collection('users').get()
      const queryTransaction = await p.ref.collection('transactions').get()
      const transactions = queryTransaction.docs.map((t: any) => ({...t.data(), id: t.id})) || []
      return {
        ...p.data(),
        data: get(p.data(), 'data', null),
        type: get(p.data(), 'type', null),
        users: users.docs.map((u: any) => ({...u.data(), id: u.id, transaction: transactions.find((t: any) => t.data.user.id === u.id) || null})),
        transactions,
      }
    }))
    // console.log(await allEvents)
    useBookingStore().setAllScheduling(await allEvents)
  })

  return snapshot
}

export const searchScheduling = async (payload: any) => {
  changeLoading(true)
  try {
    const scheduling: any = await searchCourtsAvailable(payload)
    const schedulingMap = scheduling.data.data.map((d: any) => ({...d, courts: d.courts.map((c: any) => ({...c, selected: false}))}))

    useVenueStore().setListCourtReservation(schedulingMap[0].courts)
    useVenueStore().setBenefitByAvailable(get(schedulingMap[0], 'program', null))
    useVenueStore().setPriceNotAvailable(false)
  } catch (e: any) {
    if (e.response.status === 404) {
      useVenueStore().setPriceNotAvailable(true)
      useVenueStore().setListCourtReservation([])
      useVenueStore().setBenefitByAvailable([])
    }
  }
  changeLoading(false)
}

export const resetCourts = () => {
  useVenueStore().setListCourtReservation([])
  useVenueStore().setBenefitByAvailable([])
  useVenueStore().setPriceNotAvailable(false)
}

export const searchUserByLoyalties = async (user_id: string) => {
  changeLoading(true)

  const loyaltyByUser = await getUser_service(user_id)
  useBookingStore().setLoyaltyByUser(loyaltyByUser)

  changeLoading(false)
}

export const setSlotByTags = async (date:string, sport: string) => {
  changeLoading(true)
  const getDay = Number(moment(date).format('d'))
  const allSlots = await getAllSlots_service(getDay, sport)

  useBookingStore().setSlotsBytags(allSlots.data.data)

